324	// Claim 由调用方传入当前时间，为活动中的设备领取当前可执行的操作。
325	//
326	// 派发新的下载或安装操作要求设备在线、当前时间位于维护窗口 [start, end) 内、
327	// 所在批次已被前一批全部成功放行。首次领取下载前会再次核对设备当前版本，
328	// 不兼容则将该设备（带阶段、原因和时间）记为失败，返回 ErrIncompatibleVersion。
329	// 已领取但未完成的操作再次查询时返回同一标识，不要求在线或位于窗口内。
330	// 离线设备保留待办；离线或窗口外暂无可领取的新操作时返回 (nil, nil)。
331	// 时间缺失或相对本活动已接受的时间倒退时拒绝，且不改变状态。
332	func (s *Store) Claim(campaignID, deviceID string, at time.Time) (*Operation, error) {
333		s.mu.Lock()
334		defer s.mu.Unlock()
335		if err := s.checkOpen(); err != nil {
336			return nil, err
337		}
338		c, cd, err := s.lookupCampaignDevice(campaignID, deviceID)
339		if err != nil {
340			return nil, err
341		}
342		if at.IsZero() {
343			return nil, ErrInvalidTime
344		}
345		if at.Before(c.LastTime) {
346			return nil, fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
347		}
348		var op *Operation
349		var reject error
350		err = s.commit(func() error {
351			// 到达截止时间：未结束设备全部超时并落盘，本次领取拒绝。
352			// 即使查询的设备已有终态，其他未结束设备仍要级联超时。
353			if !at.Before(c.Deadline) {
354				c.LastTime = at
355				s.applyTimeout(c, at)
356				reject = ErrCampaignEnded
357				return nil
358			}
359			if c.Ended {
360				// 纯拒绝路径：不推进时间基线，不改状态。
361				reject = ErrCampaignEnded
362				return nil
363			}
364			if isTerminal(cd.Status) {
365				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, deviceID)
366				return nil
367			}
368			c.LastTime = at
369			// 已领取但未完成的操作：查询仍返回原标识，不要求在线或位于窗口内。
370			if out := outstandingOp(c, cd); out != nil {
371				op = out
372				return nil
373			}
374			// 尚未领取的新阶段：先看批次是否放行（不放行时无操作可领）。
375			if !s.batchOpen(c, cd) {
376				return nil
377			}
378			if !s.devices[deviceID].Online {
379				return nil // 离线保留待办，上线后继续
380			}
381			if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
382				return nil // 窗口外不派发新操作；窗口为 [start, end)
383			}
384			if !cd.Download.Claimed {
385				// 首次领取下载前再次检查当前版本。
386				current := s.devices[deviceID].Version
387				if !containsString(s.versions[c.Target].AllowedFrom, current) {
388					reason := fmt.Sprintf("version %s is not compatible with target %s", current, c.Target)
389					// 该设备在下载阶段失败：领取即触发，记录阶段、原因和时间。
390					cd.Download.Claimed = true
391					cd.Download.ClaimedAt = at
392					cd.Download.HasResult = true
393					cd.Download.Success = false
394					cd.Download.Reason = reason
395					cd.Download.At = at
396					s.failDevice(c, cd, StageDownload, reason, at)
397					reject = fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, deviceID, current)
398					return nil
399				}
400				cd.Download.Claimed = true
401				cd.Download.ClaimedAt = at
402				cd.Status = DeviceDownloading
403				cd.At = at
404				op = &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageDownload}
405				return nil
406			}
407			// 下载已成功：领取安装（尚未领取的安装仍须在线且位于窗口内）。
408			cd.Install.Claimed = true
409			cd.Install.ClaimedAt = at
410			cd.Status = DeviceInstalling
411			cd.At = at
412			op = &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageInstall}
413			return nil
414		})
415		if err != nil {
416			return nil, err
417		}
418		if reject != nil {
419			return nil, reject
420		}
421		return op, nil
422	}
423	
424	// outstandingOp 返回设备已领取但尚无结果的操作；没有则返回 nil。
425	func outstandingOp(c *campaignState, cd *campaignDevice) *Operation {
426		switch {
427		case cd.Download.Claimed && !cd.Download.HasResult:
428			return &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageDownload}
429		case cd.Install.Claimed && !cd.Install.HasResult:
430			return &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageInstall}
431		default:
432			return nil
433		}
434	}
435	
436	// batchOpen 判断设备所在批次是否已放行：前序所有设备必须全部成功。
437	func (s *Store) batchOpen(c *campaignState, cd *campaignDevice) bool {
438		for _, other := range c.Devices {
439			if other.Batch < cd.Batch && other.Status != DeviceSucceeded {
440				return false
441			}
442		}
443		return true
444	}
445	
446	// SubmitResult 接收设备提交的操作结果。
447	//
448	// 相同操作的相同结果重复提交返回成功，但不增加历史、不重复放行批次；
449	// 改用不同结果、跳过未领取阶段、提交其他设备的操作、活动结束后的新结果
450	// 均报错且不改变状态；已接受结果的重复提交在活动结束后仍有效。
451	// 下载完成后才能领取并安装；设备失败记录阶段、原因和时间，同批其他设备
452	// 继续完成，后续批次记为未执行。安装成功须附带版本等于目标版本的合规上报，
453	// 影子与活动在同一次持久化中更新。普通设备上报不经过本方法，也不会推进活动。
454	func (s *Store) SubmitResult(res OperationResult) error {
455		s.mu.Lock()
456		defer s.mu.Unlock()
457		if err := s.checkOpen(); err != nil {
458			return err
459		}
460		c, cd, err := s.lookupCampaignDevice(res.CampaignID, res.DeviceID)
461		if err != nil {
462			return err
463		}
464		if res.At.IsZero() {
465			return ErrInvalidTime
466		}
467		// 定位操作标识所属阶段；不属于本设备的操作一律视为未知。
468		var stage string
469		var op *opState
470		switch res.OperationID {
471		case cd.Download.ID:
472			stage, op = StageDownload, &cd.Download
473		case cd.Install.ID:
474			stage, op = StageInstall, &cd.Install
475		default:
476			return fmt.Errorf("%w: %s", ErrOperationNotFound, res.OperationID)
477		}
478		// 已接受结果：相同结果幂等（活动结束后仍有效，不增加历史、不重复放行），
479		// 不推进时间基线；不同结果冲突。均不改变状态。
480		if op.HasResult {
481			if resultMatches(op, res) {
482				return nil
483			}
484			return fmt.Errorf("%w: operation %s", ErrResultConflict, res.OperationID)
485		}
486		if res.At.Before(c.LastTime) {
487			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, res.At, c.LastTime)
488		}
489		if !op.Claimed {
490			// 标识是本设备未来阶段的操作但尚未领取：属于跳过阶段。
491			return fmt.Errorf("%w: %s", ErrOperationNotClaimed, res.OperationID)
492		}
493		if !res.Success && res.Reason == "" {
494			return ErrInvalidReason
495		}
496		if res.Success && stage == StageInstall {
497			if err := s.validateInstallReport(res); err != nil {
498				return err
499			}
500		}
501		var reject error
502		err = s.commit(func() error {
503			// 到达截止时间：未结束设备全部超时并落盘；新结果（非重复）不再接受。
504			if !res.At.Before(c.Deadline) {
505				c.LastTime = res.At
506				s.applyTimeout(c, res.At)
507				reject = ErrCampaignEnded
508				return nil
509			}
510			if c.Ended {
511				// 活动结束后的新结果：拒绝且不改状态（重复结果已在提交前处理）。
512				reject = ErrCampaignEnded
513				return nil
514			}
515			if isTerminal(cd.Status) {
516				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, res.DeviceID)
517				return nil
518			}
519			c.LastTime = res.At
520			op.HasResult = true
521			op.Success = res.Success
522			op.Reason = res.Reason
523			op.At = res.At
524			if !res.Success {
525				s.failDevice(c, cd, stage, res.Reason, res.At)
526				return nil
527			}
528			if stage == StageDownload {
529				cd.Status = DeviceReady
530				cd.Phase = StageInstall
531				cd.At = res.At
532			} else {
533				// 安装成功：附带上报与活动同时更新、一起持久化。
534				s.applyInstallReport(cd.DeviceID, res, res.At)
535				op.ResultSeq = res.Seq
536				op.ResultVersion = res.Version
537				op.ResultConfig = cloneRaw(res.Config)
538				cd.Status = DeviceSucceeded
539				cd.Phase = StageInstall
540				cd.Reason = ""
541				cd.At = res.At
542			}
543			c.Results = append(c.Results, ResultRecord{
544				DeviceID:    cd.DeviceID,
545				OperationID: op.ID,
546				Stage:       stage,
547				Success:     true,
548				Version:     op.ResultVersion,
549				At:          res.At,
550			})
551			s.settle(c, res.At)
552			return nil
553		})
554		if err != nil {
555			return err
556		}
557		return reject
558	}
559	
560	// resultMatches 判断提交是否为已接受结果的重复提交（同一操作、相同结果）。
561	// 安装成功结果还须附带相同的上报（序号、版本、配置）；发生时间不参与判定，
562	// 使活动结束后的重复提交仍然有效。
563	func resultMatches(op *opState, res OperationResult) bool {
564		if op.Success != res.Success || op.Reason != res.Reason {
565			return false
566		}
567		if op.Success && op.ResultSeq != 0 {
568			return op.ResultSeq == res.Seq &&
569				op.ResultVersion == res.Version &&
570				rawEqual(op.ResultConfig, res.Config)
571		}
572		return true
573	}
574	
575	// validateInstallReport 按现有上报规则校验安装成功附带的设备上报，
576	// 且版本必须等于目标版本。只校验，不改状态。
577	func (s *Store) validateInstallReport(res OperationResult) error {
578		d := s.devices[res.DeviceID]
579		if res.Seq == 0 {
580			return fmt.Errorf("%w: report sequence", ErrInvalidReport)
581		}
582		if res.Version == "" {
583			return fmt.Errorf("%w: report version", ErrInvalidReport)
584		}
585		if res.Version != s.campaigns[res.CampaignID].Target {
586			return fmt.Errorf("%w: version %s", ErrInvalidReport, res.Version)
587		}
588		if _, err := validateConfig(res.Config); err != nil {
589			return fmt.Errorf("%w: config", ErrInvalidReport)
590		}
591		switch {
592		case res.Seq < d.LastSeq:
593			return fmt.Errorf("%w: stale sequence", ErrInvalidReport)
594		case res.Seq == d.LastSeq:
595			if !(res.Version == d.Version && res.At.Equal(d.LastReportTime) && rawEqual(res.Config, d.Reported)) {
596				return fmt.Errorf("%w: sequence conflict", ErrInvalidReport)
597			}
598		}
599		return nil
600	}
601	
602	// applyInstallReport 按 Report 的既有规则写入影子（调用方已校验）。
603	func (s *Store) applyInstallReport(deviceID string, res OperationResult, at time.Time) {
604		d := s.devices[deviceID]
605		if res.Seq == d.LastSeq {
606			// 相同序号的完全重复上报：影子不变，只随活动一起落盘。
607			return
608		}
609		d.Reported = cloneRaw(res.Config)
610		d.Version = res.Version
611		d.Online = true
612		d.LastSeq = res.Seq
613		d.LastReportTime = at
614		d.refreshDiff(at)
615	}
616	
617	// failDevice 将设备记为失败，记录阶段、原因和时间；后续批次全部记为未执行，
618	// 本批其他设备继续。若全部设备已到终态，则活动以失败结束。
619	func (s *Store) failDevice(c *campaignState, cd *campaignDevice, phase, reason string, at time.Time) {
620		cd.Status = DeviceFailed
621		cd.Phase = phase
622		cd.Reason = reason
623		cd.At = at
624		c.Results = append(c.Results, ResultRecord{
625			DeviceID:    cd.DeviceID,
626			OperationID: opIDFor(cd, phase),
627			Stage:       phase,
628			Success:     false,
629			Reason:      reason,
630			At:          at,
631		})
632		for _, other := range c.Devices {
633			if other.Batch > cd.Batch && !isTerminal(other.Status) {
634				other.Status = DeviceSkipped
635				other.Phase = pendingPhase(other)
636				other.Reason = "not executed: previous batch failed"
637				other.At = at
638			}
639		}
640		s.settle(c, at)
641	}
642	
643	func opIDFor(cd *campaignDevice, phase string) string {
644		if phase == StageInstall {
645			return cd.Install.ID
646		}
647		return cd.Download.ID
648	}
649	
650	// pendingPhase 返回设备尚未完成的阶段：下载成功后停留在安装阶段。
651	func pendingPhase(cd *campaignDevice) string {
652		if cd.Download.HasResult && cd.Download.Success {
653			return StageInstall
654		}
655		return StageDownload
656	}
657	
658	// applyTimeout 在当前时间达到截止时间时，把所有未结束设备记为超时，
659	// 已有终态保持不变，活动记为失败并结束。
660	func (s *Store) applyTimeout(c *campaignState, at time.Time) {
661		if c.Ended {
662			return
663		}
664		for _, cd := range c.Devices {
665			if isTerminal(cd.Status) {
666				continue
667			}
668			cd.Status = DeviceTimeout
669			cd.Phase = pendingPhase(cd)
670			cd.Reason = "deadline exceeded"
671			cd.At = at
672		}
673		c.Status = CampaignFailed
674		c.Ended = true
675		c.EndedAt = at
676	}
677	
678	// settle 在全部设备到达终态时结束活动：全部成功则成功，否则失败。
679	func (s *Store) settle(c *campaignState, at time.Time) {
680		allSucceeded := true
681		for _, cd := range c.Devices {
682			if !isTerminal(cd.Status) {
683				return
684			}
685			if cd.Status != DeviceSucceeded {
686				allSucceeded = false
687			}
688		}
689		c.Ended = true
690		c.EndedAt = at
691		if allSucceeded {
692			c.Status = CampaignSucceeded
693		} else {
694			c.Status = CampaignFailed
695		}
696	}
697	
698	func isTerminal(status string) bool {
699		switch status {
700		case DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped:
701			return true
702		default:
703			return false
704		}
705	}
706	
707	// AdvanceCampaign 用调用方给出的当前时间推进活动：到达截止时间时把未结束
708	// 设备全部记为超时并结束活动。时间缺失或相对已接受时间倒退时拒绝且不改状态。
709	// 未到截止时间或活动已结束时为空操作。
710	func (s *Store) AdvanceCampaign(campaignID string, at time.Time) error {
711		s.mu.Lock()
712		defer s.mu.Unlock()
713		if err := s.checkOpen(); err != nil {
714			return err
715		}
716		c, err := s.lookupCampaign(campaignID)
717		if err != nil {
718			return err
719		}
720		if at.IsZero() {
721			return ErrInvalidTime
722		}
723		if at.Before(c.LastTime) {
724			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
725		}
726		if c.Ended {
727			return nil
728		}
729		if at.Before(c.Deadline) {
730			// 仅推进时间基线也持久化，使重开后的倒退判断仍然有效。
731			return s.commit(func() error { c.LastTime = at; return nil })
732		}
733		return s.commit(func() error {
734			c.LastTime = at
735			s.applyTimeout(c, at)
736			return nil
737		})
738	}
739	
740	func (s *Store) lookupCampaign(campaignID string) (*campaignState, error) {
741		if campaignID == "" {
742			return nil, ErrInvalidCampaignID
743		}
744		c, ok := s.campaigns[campaignID]
745		if !ok {
746			return nil, fmt.Errorf("%w: %s", ErrCampaignNotFound, campaignID)
747		}
748		return c, nil
749	}
750	
751	func (s *Store) lookupCampaignDevice(campaignID, deviceID string) (*campaignState, *campaignDevice, error) {
752		c, err := s.lookupCampaign(campaignID)
753		if err != nil {
754			return nil, nil, err
755		}
756		if deviceID == "" {
757			return nil, nil, ErrInvalidDeviceID
758		}
759		i, ok := c.index[deviceID]
760		if !ok {
761			return nil, nil, fmt.Errorf("%w: %s", ErrDeviceNotInCampaign, deviceID)
762		}
763		return c, c.Devices[i], nil
764	}
765	
766	// DeviceStatusView 是一台设备在活动中的状态快照。
767	type DeviceStatusView struct {
768		DeviceID string
769		Batch    int
770		// Status 取 Device* 状态常量。
771		Status string
772		// Phase 是设备当前停留或失败的阶段（download/install）。
773		Phase string
774		// Reason 是失败、超时或未执行（skipped）的原因；成功时为空。
775		Reason string
776		// At 是进入当前状态的时间。
777		At time.Time
778		// DownloadID/InstallID 是两个阶段操作的稳定标识。
779		DownloadID string
780		InstallID  string
781	}
782	
783	// BatchView 是一个批次内所有设备的状态，按提交次序排列。
784	type BatchView struct {
785		Index   int
786		Devices []DeviceStatusView
787	}
788	
789	// CampaignView 是分批升级活动的只读快照。
790	type CampaignView struct {
791		ID            string
792		Operator      string
793		TargetVersion string
794		CreatedAt     time.Time
795		BatchSize     int
796		WindowStart   time.Time
797		WindowEnd     time.Time
798		Deadline      time.Time
799		// Status 取 Campaign* 状态常量。
800		Status  string
801		Ended   bool
802		EndedAt time.Time
803		// Devices 按提交次序给出每台设备的状态。
804		Devices []DeviceStatusView
805		// Batches 按批次号分组，保留设备提交次序。
806		Batches []BatchView
807		// Results 是按接受顺序排列的结果历史（重复提交不产生新记录）。
808		Results []ResultRecord
809	}
810	
811	// GetCampaign 查询活动：创建者、目标版本、每批设备状态、
812	// 失败或超时原因及结果历史。返回数据为独立副本。
813	func (s *Store) GetCampaign(campaignID string) (CampaignView, error) {
814		s.mu.Lock()
815		defer s.mu.Unlock()
816		if err := s.checkOpen(); err != nil {
817			return CampaignView{}, err
818		}
819		c, err := s.lookupCampaign(campaignID)
820		if err != nil {
821			return CampaignView{}, err
822		}
823		v := CampaignView{
824			ID:            c.ID,
825			Operator:      c.Operator,
826			TargetVersion: c.Target,
827			CreatedAt:     c.CreatedAt,
828			BatchSize:     c.BatchSize,
829			WindowStart:   c.WindowStart,
830			WindowEnd:     c.WindowEnd,
831			Deadline:      c.Deadline,
832			Status:        c.Status,
833			Ended:         c.Ended,
834			EndedAt:       c.EndedAt,
835			Results:       make([]ResultRecord, len(c.Results)),
836		}
837		copy(v.Results, c.Results)
838		for _, cd := range c.Devices {
839			dv := DeviceStatusView{
840				DeviceID:   cd.DeviceID,
841				Batch:      cd.Batch,
842				Status:     cd.Status,
843				Phase:      cd.Phase,
844				Reason:     cd.Reason,
845				At:         cd.At,
846				DownloadID: cd.Download.ID,
847				InstallID:  cd.Install.ID,
848			}
849			v.Devices = append(v.Devices, dv)
850			for len(v.Batches) <= cd.Batch {
851				v.Batches = append(v.Batches, BatchView{Index: len(v.Batches)})
852			}
853			v.Batches[cd.Batch].Devices = append(v.Batches[cd.Batch].Devices, dv)
854		}
855		return v, nil
856	}
857	
858	// DeviceWork 是设备当前版本与待执行操作的查询结果。
859	type DeviceWork struct {
860		DeviceID string
861		Version  string
862		Online   bool
863		// CampaignID 是设备当前所在的未结束活动；没有时为空。
864		CampaignID string
865		// Pending 是设备仍待完成的操作（至多一个）：已领取未完成或下一阶段可领取。
866		Pending *Operation
867		// PendingClaimed 表示 Pending 是否已领取（未领取的安装仍须等维护窗口）。
868		PendingClaimed bool
869	}
870	
871	// GetDeviceWork 查询设备当前版本及其待执行操作。
872	func (s *Store) GetDeviceWork(deviceID string) (DeviceWork, error) {
873		s.mu.Lock()
874		defer s.mu.Unlock()
875		if err := s.checkOpen(); err != nil {
876			return DeviceWork{}, err
877		}
878		d, err := s.lookup(deviceID)
879		if err != nil {
880			return DeviceWork{}, err
881		}
882		w := DeviceWork{DeviceID: deviceID, Version: d.Version, Online: d.Online}
883		for id, c := range s.campaigns {
884			if c.Ended {
885				continue
886			}
887			i, ok := c.index[deviceID]
888			if !ok {
889				continue
890			}
891			cd := c.Devices[i]
892			w.CampaignID = id
893			if out := outstandingOp(c, cd); out != nil {
894				w.Pending = out
895				w.PendingClaimed = true
896			} else if !isTerminal(cd.Status) {
897				kind := StageDownload
898				id := cd.Download.ID
899				if cd.Download.HasResult {
900					kind, id = StageInstall, cd.Install.ID
901				}
902				w.Pending = &Operation{ID: id, CampaignID: c.ID, DeviceID: deviceID, Kind: kind}
903				w.PendingClaimed = false
904			}
905			break
906		}
907		return w, nil
908	}
909	
910	// ListUpgrades 返回已登记的全部升级目标版本，按目标版本字典序排列。
911	func (s *Store) ListUpgrades() ([]VersionSpec, error) {
912		s.mu.Lock()
913		defer s.mu.Unlock()
914		if err := s.checkOpen(); err != nil {
915			return nil, err
916		}
917		out := make([]VersionSpec, 0, len(s.versions))
918		for _, v := range s.versions {
919			out = append(out, VersionSpec{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)})
920		}
921		sort.Slice(out, func(i, j int) bool { return out[i].Target < out[j].Target })
922		return out, nil
923	}
