151	// restoreVersions 恢复并校验版本登记。
152	func (s *Store) restoreVersions(disk map[string]diskVersion) error {
153		out := make(map[string]*versionState, len(disk))
154		for k, dv := range disk {
155			if k == "" || dv.Target == "" || k != dv.Target {
156				return fmt.Errorf("%w: invalid upgrade version entry", ErrCorruptStorage)
157			}
158			if err := validateAllowedFrom(dv.Target, dv.AllowedFrom); err != nil {
159				return fmt.Errorf("%w: version %s: %v", ErrCorruptStorage, dv.Target, err)
160			}
161			out[k] = &versionState{Target: dv.Target, AllowedFrom: append([]string(nil), dv.AllowedFrom...)}
162		}
163		s.versions = out
164		return nil
165	}
166	
167	// restoreCampaigns 恢复活动并做一致性校验。版本、设备引用、操作标识、
168	// 结果历史都必须自洽，否则整个存储拒绝打开。
169	func (s *Store) restoreCampaigns(disk map[string]diskCampaign) error {
170		out := make(map[string]*campaignState, len(disk))
171		for id, dc := range disk {
172			if id == "" || dc.ID != id {
173				return fmt.Errorf("%w: campaign id mismatch", ErrCorruptStorage)
174			}
175			if dc.Operator == "" || dc.Target == "" || dc.BatchSize <= 0 {
176				return fmt.Errorf("%w: campaign %s invalid", ErrCorruptStorage, id)
177			}
178			if dc.CreatedAt.IsZero() || dc.WindowStart.IsZero() || dc.WindowEnd.IsZero() || dc.Deadline.IsZero() {
179				return fmt.Errorf("%w: campaign %s missing time", ErrCorruptStorage, id)
180			}
181			if !dc.WindowStart.Before(dc.WindowEnd) || !dc.Deadline.After(dc.CreatedAt) {
182				return fmt.Errorf("%w: campaign %s invalid time range", ErrCorruptStorage, id)
183			}
184			if _, ok := s.versions[dc.Target]; !ok {
185				return fmt.Errorf("%w: campaign %s target %s missing", ErrCorruptStorage, id, dc.Target)
186			}
187			if dc.Status != CampaignRunning && dc.Status != CampaignSucceeded && dc.Status != CampaignFailed {
188				return fmt.Errorf("%w: campaign %s bad status", ErrCorruptStorage, id)
189			}
190			if dc.Ended == (dc.Status == CampaignRunning) {
191				return fmt.Errorf("%w: campaign %s ended/status mismatch", ErrCorruptStorage, id)
192			}
193			if len(dc.Devices) == 0 {
194				return fmt.Errorf("%w: campaign %s has no devices", ErrCorruptStorage, id)
195			}
196			c := &campaignState{
197				ID:          dc.ID,
198				Operator:    dc.Operator,
199				Target:      dc.Target,
200				CreatedAt:   dc.CreatedAt,
201				BatchSize:   dc.BatchSize,
202				WindowStart: dc.WindowStart,
203				WindowEnd:   dc.WindowEnd,
204				Deadline:    dc.Deadline,
205				LastTime:    dc.LastTime,
206				Status:      dc.Status,
207				Ended:       dc.Ended,
208				EndedAt:     dc.EndedAt,
209				index:       map[string]int{},
210			}
211			if c.LastTime.IsZero() {
212				c.LastTime = c.CreatedAt
213			}
214			if c.LastTime.Before(c.CreatedAt) {
215				return fmt.Errorf("%w: campaign %s last time before creation", ErrCorruptStorage, id)
216			}
217			seen := map[string]bool{}
218			for i, dd := range dc.Devices {
219				if dd.DeviceID == "" || seen[dd.DeviceID] {
220					return fmt.Errorf("%w: campaign %s device list invalid", ErrCorruptStorage, id)
221				}
222				seen[dd.DeviceID] = true
223				if _, ok := s.devices[dd.DeviceID]; !ok {
224					return fmt.Errorf("%w: campaign %s device %s missing", ErrCorruptStorage, id, dd.DeviceID)
225				}
226				if dd.Batch != i/dc.BatchSize {
227					return fmt.Errorf("%w: campaign %s batch mismatch", ErrCorruptStorage, id)
228				}
229				if !validDeviceStatus(dd.Status) {
230					return fmt.Errorf("%w: campaign %s bad device status", ErrCorruptStorage, id)
231				}
232				if dd.Phase != StageDownload && dd.Phase != StageInstall {
233					return fmt.Errorf("%w: campaign %s bad phase", ErrCorruptStorage, id)
234				}
235				wantDL := operationID(id, dd.DeviceID, StageDownload)
236				wantIN := operationID(id, dd.DeviceID, StageInstall)
237				if dd.Download.ID != wantDL || dd.Install.ID != wantIN {
238					return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
239				}
240				// 终态设备必须带时间；失败还须带阶段与原因。
241				if isTerminal(dd.Status) && dd.At.IsZero() {
242					return fmt.Errorf("%w: campaign %s terminal without time", ErrCorruptStorage, id)
243				}
244				if dd.Status == DeviceFailed && dd.Reason == "" {
245					return fmt.Errorf("%w: campaign %s failure without reason", ErrCorruptStorage, id)
246				}
247				if dd.Status == DeviceSucceeded &&
248					!(dd.Download.HasResult && dd.Download.Success && dd.Install.HasResult && dd.Install.Success) {
249					return fmt.Errorf("%w: campaign %s succeeded device without results", ErrCorruptStorage, id)
250				}
251				if dd.Status == DeviceFailed {
252					failedOp := dd.Download
253					if dd.Phase == StageInstall {
254						failedOp = dd.Install
255					}
256					if !failedOp.HasResult || failedOp.Success {
257						return fmt.Errorf("%w: campaign %s failed device without failed result", ErrCorruptStorage, id)
258					}
259				}
260				if dd.Status == DeviceReady && !(dd.Download.HasResult && dd.Download.Success) {
261					return fmt.Errorf("%w: campaign %s ready device without download", ErrCorruptStorage, id)
262				}
263				for _, o := range []diskOp{dd.Download, dd.Install} {
264					if o.HasResult {
265						if !o.Claimed {
266							return fmt.Errorf("%w: campaign %s unclaimed result", ErrCorruptStorage, id)
267						}
268						if o.At.IsZero() {
269							return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
270						}
271						if !o.Success && o.Reason == "" {
272							return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
273						}
274					}
275					if o.Claimed && o.ClaimedAt.IsZero() {
276						return fmt.Errorf("%w: campaign %s claim without time", ErrCorruptStorage, id)
277					}
278				}
279				if dd.Install.HasResult && !(dd.Download.HasResult && dd.Download.Success) {
280					return fmt.Errorf("%w: campaign %s install before download", ErrCorruptStorage, id)
281				}
282				if dd.Install.Claimed && !(dd.Download.HasResult && dd.Download.Success) {
283					return fmt.Errorf("%w: campaign %s install claimed before download", ErrCorruptStorage, id)
284				}
285				if dd.Install.HasResult && dd.Install.Success {
286					if dd.Install.ResultVersion != dc.Target {
287						return fmt.Errorf("%w: campaign %s install version mismatch", ErrCorruptStorage, id)
288					}
289					if _, ok := decodeObject(dd.Install.ResultConfig); !ok {
290						return fmt.Errorf("%w: campaign %s install config invalid", ErrCorruptStorage, id)
291					}
292				}
293				cd := &campaignDevice{
294					DeviceID: dd.DeviceID,
295					Batch:    dd.Batch,
296					Status:   dd.Status,
297					Phase:    dd.Phase,
298					Reason:   dd.Reason,
299					At:       dd.At,
300					Download: decodeOp(dd.Download),
301					Install:  decodeOp(dd.Install),
302				}
303				c.index[cd.DeviceID] = len(c.Devices)
304				c.Devices = append(c.Devices, cd)
305			}
306			seenResult := map[string]bool{}
307			for _, dr := range dc.Results {
308				if dr.At.IsZero() {
309					return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
310				}
311				if _, ok := c.index[dr.DeviceID]; !ok {
312					return fmt.Errorf("%w: campaign %s result device mismatch", ErrCorruptStorage, id)
313				}
314				if dr.Stage != StageDownload && dr.Stage != StageInstall {
315					return fmt.Errorf("%w: campaign %s result stage invalid", ErrCorruptStorage, id)
316				}
317				wantOp := operationID(id, dr.DeviceID, dr.Stage)
318				if dr.OperationID != wantOp {
319					return fmt.Errorf("%w: campaign %s result op id mismatch", ErrCorruptStorage, id)
320				}
321				key := dr.OperationID
322				if seenResult[key] {
323					return fmt.Errorf("%w: campaign %s duplicated result history", ErrCorruptStorage, id)
324				}
325				seenResult[key] = true
326				if !dr.Success && dr.Reason == "" {
327					return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
328				}
329				c.Results = append(c.Results, ResultRecord{
330					DeviceID:    dr.DeviceID,
331					OperationID: dr.OperationID,
332					Stage:       dr.Stage,
333					Success:     dr.Success,
334					Reason:      dr.Reason,
335					Version:     dr.Version,
336					At:          dr.At,
337				})
338			}
339			out[id] = c
340		}
341		// 设备不能同时参加多个未结束活动。
342		busy := map[string]string{}
343		for id, c := range out {
344			if c.Ended {
345				continue
346			}
347			for _, cd := range c.Devices {
348				if other, ok := busy[cd.DeviceID]; ok {
349					return fmt.Errorf("%w: device %s in active campaigns %s and %s",
350						ErrCorruptStorage, cd.DeviceID, other, id)
351				}
352				busy[cd.DeviceID] = id
353			}
354		}
355		s.campaigns = out
356		return nil
357	}
358	
359	func validDeviceStatus(status string) bool {
360		switch status {
361		case DevicePending, DeviceDownloading, DeviceReady, DeviceInstalling,
362			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped:
363			return true
364		default:
365			return false
366		}
367	}
368

