470	func outstandingOp(c *campaignState, cd *campaignDevice) *Operation {
471		switch {
472		case cd.Download.Claimed && !cd.Download.HasResult:
473			return &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageDownload}
474		case cd.Install.Claimed && !cd.Install.HasResult:
475			return &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageInstall}
476		case cd.Rollback.Claimed && !cd.Rollback.HasResult:
477			return &Operation{ID: cd.Rollback.ID, CampaignID: c.ID, DeviceID: cd.DeviceID,
478				Kind: StageRollback, Version: cd.RollbackTarget}
479		default:
480			return nil
481		}
482	}
483	
484	// batchOpen 判断设备所在批次是否已放行：前序所有设备必须全部成功。
485	func (s *Store) batchOpen(c *campaignState, cd *campaignDevice) bool {
486		for _, other := range c.Devices {
487			if other.Batch < cd.Batch && other.Status != DeviceSucceeded {
488				return false
489			}
490		}
491		return true
492	}
493	
494	// SubmitResult 接收设备提交的操作结果。
495	//
496	// 相同操作的相同结果重复提交返回成功，但不增加历史、不重复放行批次；
497	// 改用不同结果、跳过未领取阶段、提交其他设备的操作、活动结束后的新结果
498	// 均报错且不改变状态；已接受结果的重复提交在活动结束后仍有效。
499	// 下载完成后才能领取并安装；设备失败记录阶段、原因和时间，同批其他设备
500	// 继续完成，后续批次记为未执行。安装成功须附带版本等于目标版本的合规上报，
501	// 影子与活动在同一次持久化中更新。普通设备上报不经过本方法，也不会推进活动。
502	func (s *Store) SubmitResult(res OperationResult) error {
503		s.mu.Lock()
504		defer s.mu.Unlock()
505		if err := s.checkOpen(); err != nil {
506			return err
507		}
508		c, cd, err := s.lookupCampaignDevice(res.CampaignID, res.DeviceID)
509		if err != nil {
510			return err
511		}
512		if res.At.IsZero() {
513			return ErrInvalidTime
514		}
515		// 定位操作标识所属阶段；不属于本设备的操作一律视为未知。
516		var stage string
517		var op *opState
518		switch res.OperationID {
519		case cd.Download.ID:
520			stage, op = StageDownload, &cd.Download
521		case cd.Install.ID:
522			stage, op = StageInstall, &cd.Install
523		default:
524			return fmt.Errorf("%w: %s", ErrOperationNotFound, res.OperationID)
525		}
526		// 已接受结果：相同结果幂等（活动结束后仍有效，不增加历史、不重复放行），
527		// 不推进时间基线；不同结果冲突。均不改变状态。
528		if op.HasResult {
529			if resultMatches(op, res) {
530				return nil
531			}
532			return fmt.Errorf("%w: operation %s", ErrResultConflict, res.OperationID)
533		}
534		if res.At.Before(c.LastTime) {
535			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, res.At, c.LastTime)
536		}
537		if !op.Claimed {
538			// 标识是本设备未来阶段的操作但尚未领取：属于跳过阶段。
539			return fmt.Errorf("%w: %s", ErrOperationNotClaimed, res.OperationID)
540		}
541		if !res.Success && res.Reason == "" {
542			return ErrInvalidReason
543		}
544		if res.Success && stage == StageInstall {
545			if err := s.validateInstallReport(res); err != nil {
546				return err
547			}
548		}
549		var reject error
550		err = s.commit(func() error {
551			// 到达截止时间：未结束设备全部超时并落盘；新结果（非重复）不再接受。
552			if !res.At.Before(c.Deadline) {
553				c.LastTime = res.At
554				s.applyTimeout(c, res.At)
555				reject = ErrCampaignEnded
556				return nil
557			}
558			if c.Ended {
559				// 活动结束后的新结果：拒绝且不改状态（重复结果已在提交前处理）。
560				reject = ErrCampaignEnded
561				return nil
562			}
563			if isTerminal(cd.Status) {
564				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, res.DeviceID)
565				return nil
566			}
567			c.LastTime = res.At
568			op.HasResult = true
569			op.Success = res.Success
570			op.Reason = res.Reason
571			op.At = res.At
572			if !res.Success {
573				s.failDevice(c, cd, stage, res.Reason, res.At)
574				return nil
575			}
576			if stage == StageDownload {
577				cd.Status = DeviceReady
578				cd.Phase = StageInstall
579				cd.At = res.At
580			} else {
581				// 安装成功：附带上报与活动同时更新、一起持久化。
582				s.applyInstallReport(cd.DeviceID, res, res.At)
583				op.ResultSeq = res.Seq
584				op.ResultVersion = res.Version
585				op.ResultConfig = cloneRaw(res.Config)
586				cd.Status = DeviceSucceeded
587				cd.Phase = StageInstall
588				cd.Reason = ""
589				cd.At = res.At
590			}
591			c.Results = append(c.Results, ResultRecord{
592				DeviceID:    cd.DeviceID,
593				OperationID: op.ID,
594				Stage:       stage,
595				Success:     true,
596				Version:     op.ResultVersion,
597				At:          res.At,
598			})
599			s.settle(c, res.At)

