// TestRollbackPersistenceReopen 验证关闭后重新打开保留目标、进度、操作标识和重复判断。
func TestRollbackPersistenceReopen(t *testing.T) {
	s, dir := setupUpgradeDir(t, "d1")
	spec := rollbackSpec()
	spec.Devices = []string{"d1"}
	spec.BatchSize = 1
	createCampaign(t, s, spec)
	bringOnline(t, s, "d1")
